-- Apply once to a fresh Supabase project. Review before production.
create extension if not exists pgcrypto;
create type public.app_role as enum ('buyer','seller','admin','super_admin');
create type public.transaction_status as enum ('awaiting_acceptance','awaiting_payment_provider','provider_payment_confirmed','item_delivery','buyer_inspection','completed','disputed','refund_pending','cancelled');
create type public.review_status as enum ('not_submitted','pending_review','approved','rejected','suspended');
create type public.dispute_status as enum ('open','under_review','resolved','rejected');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text not null default '',phone text,avatar_path text,created_at timestamptz not null default now());
create table public.user_roles(user_id uuid references auth.users(id) on delete cascade,role public.app_role not null default 'buyer',assigned_at timestamptz not null default now(),primary key(user_id,role));
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'display_name',''));insert into public.user_roles(user_id,role) values(new.id,'buyer');return new;end;$$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.has_role(uid uuid,r public.app_role) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.user_roles where user_id=uid and role=r); $$;
create table public.transactions(id uuid primary key default gen_random_uuid(),title text not null check(char_length(title) between 5 and 120),description text not null,buyer_id uuid not null references auth.users(id),seller_id uuid not null references auth.users(id),amount bigint not null check(amount>0),currency text not null default 'IDR' check(currency='IDR'),status public.transaction_status not null default 'awaiting_acceptance',buyer_accepted_at timestamptz,seller_accepted_at timestamptz,created_at timestamptz not null default now(),check(buyer_id<>seller_id));
create table public.transaction_assignments(id uuid primary key default gen_random_uuid(),transaction_id uuid not null references public.transactions(id),admin_id uuid not null references auth.users(id),assigned_by uuid not null references auth.users(id),assigned_at timestamptz not null default now(),revoked_at timestamptz);
create unique index one_active_assignment on public.transaction_assignments(transaction_id) where revoked_at is null;
create table public.transaction_messages(id uuid primary key default gen_random_uuid(),transaction_id uuid not null references public.transactions(id),sender_id uuid not null references auth.users(id),body text not null check(char_length(body) between 1 and 5000),created_at timestamptz not null default now());
create table public.disputes(id uuid primary key default gen_random_uuid(),transaction_id uuid not null unique references public.transactions(id),opened_by uuid not null references auth.users(id),reason text not null,status public.dispute_status not null default 'open',resolution text,resolved_by uuid references auth.users(id),created_at timestamptz not null default now(),resolved_at timestamptz);
create table public.admin_kyc_submissions(id uuid primary key default gen_random_uuid(),admin_user_id uuid not null references auth.users(id),legal_name text not null,phone_e164 text not null,identity_document_type text not null,identity_document_object_path text not null,selfie_object_path text,status public.review_status not null default 'pending_review',reviewer_id uuid references auth.users(id),reviewer_note text,submitted_at timestamptz not null default now(),reviewed_at timestamptz);
create table public.admin_qr_profiles(id uuid primary key default gen_random_uuid(),admin_user_id uuid not null references auth.users(id),merchant_display_name text not null,merchant_provider text not null default 'DANA_BISNIS',qr_image_object_path text not null,ownership_evidence_object_path text,status public.review_status not null default 'pending_review',reviewer_id uuid references auth.users(id),reviewer_note text,submitted_at timestamptz not null default now(),reviewed_at timestamptz);
create table public.payment_intents(id uuid primary key default gen_random_uuid(),transaction_id uuid not null references public.transactions(id),provider_code text not null,provider_payment_id text,amount bigint not null check(amount>0),status text not null default 'not_started',created_at timestamptz not null default now());
create table public.payment_events(id uuid primary key default gen_random_uuid(),payment_intent_id uuid not null references public.payment_intents(id),provider_event_id text not null,event_type text not null,signature_verified boolean not null default false,payload_digest text not null,received_at timestamptz not null default now(),unique(provider_event_id));
create table public.settlement_records(id uuid primary key default gen_random_uuid(),transaction_id uuid not null references public.transactions(id),provider_code text not null,gross_amount bigint not null,fees_amount bigint not null default 0,net_amount bigint not null,status text not null default 'not_requested',created_at timestamptz not null default now());
create table public.audit_logs(id bigint generated always as identity primary key,actor_id uuid references auth.users(id),transaction_id uuid references public.transactions(id),action text not null,details jsonb not null default '{}',created_at timestamptz not null default now());

-- RLS baseline
alter table public.profiles enable row level security;alter table public.user_roles enable row level security;alter table public.transactions enable row level security;alter table public.transaction_assignments enable row level security;alter table public.transaction_messages enable row level security;alter table public.disputes enable row level security;alter table public.admin_kyc_submissions enable row level security;alter table public.admin_qr_profiles enable row level security;alter table public.payment_intents enable row level security;alter table public.payment_events enable row level security;alter table public.settlement_records enable row level security;alter table public.audit_logs enable row level security;
create policy profile_self_read on public.profiles for select to authenticated using(id=auth.uid());create policy profile_self_update on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());create policy roles_self_read on public.user_roles for select to authenticated using(user_id=auth.uid());
create policy transaction_participant_read on public.transactions for select to authenticated using(buyer_id=auth.uid() or seller_id=auth.uid() or public.has_role(auth.uid(),'super_admin') or exists(select 1 from public.transaction_assignments a where a.transaction_id=transactions.id and a.admin_id=auth.uid() and a.revoked_at is null));create policy buyer_insert_transaction on public.transactions for insert to authenticated with check(buyer_id=auth.uid() and status='awaiting_acceptance');
create policy messages_participant_read on public.transaction_messages for select to authenticated using(exists(select 1 from public.transactions t where t.id=transaction_id and (t.buyer_id=auth.uid() or t.seller_id=auth.uid())) or exists(select 1 from public.transaction_assignments a where a.transaction_id=transaction_id and a.admin_id=auth.uid() and a.revoked_at is null) or public.has_role(auth.uid(),'super_admin'));create policy messages_participant_insert on public.transaction_messages for insert to authenticated with check(sender_id=auth.uid() and (exists(select 1 from public.transactions t where t.id=transaction_id and (t.buyer_id=auth.uid() or t.seller_id=auth.uid())) or exists(select 1 from public.transaction_assignments a where a.transaction_id=transaction_id and a.admin_id=auth.uid() and a.revoked_at is null) or public.has_role(auth.uid(),'super_admin')));
create policy dispute_participant_read on public.disputes for select to authenticated using(opened_by=auth.uid() or exists(select 1 from public.transactions t where t.id=transaction_id and (t.buyer_id=auth.uid() or t.seller_id=auth.uid())) or public.has_role(auth.uid(),'admin') or public.has_role(auth.uid(),'super_admin'));create policy dispute_party_insert on public.disputes for insert to authenticated with check(opened_by=auth.uid() and exists(select 1 from public.transactions t where t.id=transaction_id and (t.buyer_id=auth.uid() or t.seller_id=auth.uid())));
create policy own_kyc_status on public.admin_kyc_submissions for select to authenticated using(admin_user_id=auth.uid() or public.has_role(auth.uid(),'super_admin'));create policy own_qr_status on public.admin_qr_profiles for select to authenticated using(admin_user_id=auth.uid() or public.has_role(auth.uid(),'super_admin'));
create policy payment_participant_read on public.payment_intents for select to authenticated using(exists(select 1 from public.transactions t where t.id=transaction_id and (t.buyer_id=auth.uid() or t.seller_id=auth.uid())) or public.has_role(auth.uid(),'admin') or public.has_role(auth.uid(),'super_admin'));
create policy staff_payment_events_read on public.payment_events for select to authenticated using(public.has_role(auth.uid(),'admin') or public.has_role(auth.uid(),'super_admin'));create policy staff_settlement_read on public.settlement_records for select to authenticated using(public.has_role(auth.uid(),'admin') or public.has_role(auth.uid(),'super_admin'));create policy staff_audit_read on public.audit_logs for select to authenticated using(public.has_role(auth.uid(),'admin') or public.has_role(auth.uid(),'super_admin'));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('admin-private-documents','admin-private-documents',false,5242880,array['image/jpeg','image/png','application/pdf']) on conflict(id) do nothing;
-- No client policies for role changes, transaction state updates, KYC review, payment events or settlement writes.
